 import unittest
from candidate import search

class TestSearch(unittest.TestCase):
    def test_search_positive_list(self):
        self.assertEqual(search([4, 1, 2, 2, 3, 1]), 2)

    def test_search_single_element_list(self):
        self.assertEqual(search([10]), 10)

    def test_search_empty_list(self):
        self.assertEqual(search([]), -1)

    def test_search_list_with_zero(self):
        self.assertEqual(search([0]), -1)

    def test_search_list_with_one(self):
        self.assertEqual(search([1]), 1)

    def test_search_list_with_max_value(self):
        self.assertEqual(search([9, 8, 7, 6, 5]), 9)

    def test_search_list_with_max_value_less_than_length(self):
        self.assertEqual(search([9, 8, 7, 6, 5, 4]), 9)

    def test_search_list_with_multiple_max_values(self):
        self.assertEqual(search([7, 7, 6, 6, 5]), 7)

    def test_search_list_with_repeated_max_values(self):
        self.assertEqual(search([7, 7, 7, 6, 6, 5]), 7)

    def test_search_list_with_min_value(self):
        self.assertEqual(search([1, 1, 1]), 1)

    def test_search_list_with_min_value_less_than_length(self):
        self.assertEqual(search([1, 1, 1, 2]), 1)

    def test_search_list_with_only_max_value(self):
        self.assertEqual(search([7]), 7)

    def test_search_list_with_only_min_value(self):
        self.assertEqual(search([1]), 1)

    def test_search_list_with_all_same_value(self):
        self.assertEqual(search([4, 4, 4, 4]), -1)

    def test_search_list_with_no_such_value(self):
        self.assertEqual(search([5, 5, 4, 4, 4]), -1)

    def test_search_list_with_negative_values(self):
        self.assertEqual(search([3, -2, -1, 0]), -1)

if __name__ == '__main__':
    unittest.main()
